mapper.select:
select progress.question_id from user_question_progress progress
join question on question.id = progress.question_id and question.status = 'ACTIVE'
where progress.user_id = #{userId} and progress.status = 'WRONG'
and question_id > #{cursor}
order by question_id
limit #{limit}

select favorite.question_id from user_favorite_question favorite
join question on question.id = favorite.question_id and question.status = 'ACTIVE'
where favorite.user_id = #{userId}
and favorite.question_id < #{cursor}
order by favorite.question_id desc
limit #{limit}

select count(*) from user_favorite_question favorite
join question on question.id = favorite.question_id and question.status = 'ACTIVE'
where favorite.user_id = #{userId}

select exists(
    select 1 from user_favorite_question
    where user_id = #{userId} and question_id = #{questionId}
)

select distinct study_date from user_daily_question
where user_id = #{userId}
order by study_date desc
